begin;
create extension if not exists pgtap with schema extensions;
select plan(25);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)values
('00000000-0000-0000-0000-000000000000','92700000-0000-4000-8000-000000000001','authenticated','authenticated','builder-owner@example.test','',now(),now(),now()),
('00000000-0000-0000-0000-000000000000','92700000-0000-4000-8000-000000000002','authenticated','authenticated','builder-outsider@example.test','',now(),now(),now());
set local role authenticated;select set_config('request.jwt.claim.sub','92700000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"92700000-0000-4000-8000-000000000001","role":"authenticated"}',true);select public.create_business('builder-chat-test','Builder Chat Test','Builder Chat Test','corporation','retail','{"city":"Manila"}');select set_config('test.builder_org',(select id::text from public.organizations where slug='builder-chat-test'),true);
select is(public.can_business_permission(current_setting('test.builder_org')::uuid,'ai.manage'),true,'Owner can use System Builder');
select set_config('test.builder_session',(select public.start_ai_system_builder_session(current_setting('test.builder_org')::uuid,'New system design','Tell me what to change.')::text),true);
select ok(current_setting('test.builder_session')::uuid is not null,'An auditable builder session starts');
select is((select content from public.ai_system_builder_messages where session_id=current_setting('test.builder_session')::uuid),'Tell me what to change.','Assistant greeting is persisted');
select is((select event from public.ai_system_builder_events where session_id=current_setting('test.builder_session')::uuid),'session_started','Session start is audited');
select throws_ok($$insert into public.ai_system_builder_messages(organization_id,session_id,role,content)values(current_setting('test.builder_org')::uuid,current_setting('test.builder_session')::uuid,'assistant','Bypass')$$,'42501','permission denied for table ai_system_builder_messages','Clients cannot forge AI messages');
select set_config('test.builder_proposal',(select public.submit_ai_configuration_proposal(current_setting('test.builder_org')::uuid,'Restrict cashier expenses','Remove expense visibility','[{"operation":"update_permission","roleKey":"cashier","permissionKey":"expenses.read","enabled":false}]',0,'[]')::text),true);
select lives_ok($$select public.record_ai_system_builder_exchange(current_setting('test.builder_org')::uuid,current_setting('test.builder_session')::uuid,'My cashier should not see expenses.','I prepared a validated preview.',current_setting('test.builder_proposal')::uuid,'{"headline":"Restrict cashier access","summary":"Remove expense visibility","changes":[{"label":"Cashier access","after":"Remove expenses.read","impact":"Cashiers cannot view expenses"}],"warnings":[]}','request_interpreted')$$,'Validated interpretation is recorded');
select is((select count(*)from public.ai_system_builder_messages where session_id=current_setting('test.builder_session')::uuid),3::bigint,'User request and assistant preview append to chat');
select is((select proposal_id from public.ai_system_builder_messages where session_id=current_setting('test.builder_session')::uuid and proposal_id is not null),current_setting('test.builder_proposal')::uuid,'Assistant preview links the guarded proposal');
select is((select count(*)from public.ai_system_builder_events where session_id=current_setting('test.builder_session')::uuid and event='request_interpreted'),1::bigint,'Interpretation is explicitly audited');
select is((select status from public.configuration_change_sets where id=current_setting('test.builder_proposal')::uuid),'validated','Chat interpretation never auto-applies a change');
select lives_ok($$select public.record_ai_system_builder_exchange(current_setting('test.builder_org')::uuid,current_setting('test.builder_session')::uuid,'Run arbitrary JavaScript','I can only propose supported configuration changes.',null,null,'clarification_requested')$$,'Unsafe request becomes an audited clarification');
select is((select count(*)from public.ai_system_builder_messages where session_id=current_setting('test.builder_session')::uuid),5::bigint,'Clarification remains part of conversation history');
select is((select count(*)from public.ai_system_builder_events where session_id=current_setting('test.builder_session')::uuid and event='clarification_requested'),1::bigint,'Clarification action is audited');
select throws_ok($$select public.record_ai_system_builder_exchange(current_setting('test.builder_org')::uuid,current_setting('test.builder_session')::uuid,'Pretend this validated','No proposal exists',null,'{"headline":"Fake"}','request_interpreted')$$,'22023','Interpreted requests require a validated proposal and explanation.','A successful interpretation cannot omit its validated proposal');
select lives_ok($$select public.review_ai_configuration_proposal(current_setting('test.builder_org')::uuid,current_setting('test.builder_proposal')::uuid,'approved')$$,'Human approves the preview');
select is(jsonb_array_length((select public.begin_ai_configuration_apply(current_setting('test.builder_org')::uuid,current_setting('test.builder_proposal')::uuid)->'operations')),1,'Apply reads only the reviewed DSL');
select lives_ok($$select public.complete_ai_configuration_apply(current_setting('test.builder_org')::uuid,current_setting('test.builder_proposal')::uuid,'[]')$$,'Approved change completes with rollback history');
select is((select revision from public.organization_configuration_revisions where organization_id=current_setting('test.builder_org')::uuid),1::bigint,'Live system advances to revision one');
select is(jsonb_array_length(public.begin_ai_configuration_rollback(current_setting('test.builder_org')::uuid,current_setting('test.builder_proposal')::uuid)),0,'Undo retrieves the stored previous-version snapshot');
select lives_ok($$select public.complete_ai_configuration_rollback(current_setting('test.builder_org')::uuid,current_setting('test.builder_proposal')::uuid)$$,'Undo restores the previous version');
select is((select status from public.configuration_change_sets where id=current_setting('test.builder_proposal')::uuid),'rolled_back','Configuration history records the restore');
select is((select count(*)from public.configuration_change_set_events where change_set_id=current_setting('test.builder_proposal')::uuid),7::bigint,'Proposal, validation, approval, apply, and restore actions are audited');
select is((select count(*)from public.ai_system_builder_events where session_id=current_setting('test.builder_session')::uuid),3::bigint,'Every chat-side AI action has an audit event');
select set_config('request.jwt.claim.sub','92700000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"92700000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.start_ai_system_builder_session(current_setting('test.builder_org')::uuid,'Cross tenant','No access')$$,'42501','Permission denied.','Outsider cannot start a builder chat');
select is((select count(*)from public.ai_system_builder_sessions),0::bigint,'RLS hides another tenant builder history');
select *from finish();rollback;
